#define GRID 64.0
#define FRONT vec3(0.3, 0.3, 0.3)
#define BACK vec3(0.2, 0.2, 0.2)
#define INTERVAL 200.0

const float pi = atan(1.0)*4.0;
const vec2 A = vec2(1.2, 0.7);
const vec2 B = vec2(-0.2, 1);

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 cells = iResolution.xy/GRID;
    vec2 uv = mod(fragCoord, GRID)/GRID - 0.5;
    vec2 cell = vec2(ivec2(fragCoord / GRID));
    float t = length(cell - mix(A*cells,B*cells, cell.x/cells.x)+0.5)*5.0 + iTime;

    float flip;
    if (mod(t, 2.0 * INTERVAL) < INTERVAL) {
        t = mod(t, INTERVAL);
        flip = 2.0*sin(t*pi)/pi/t-1.0;
    } else {
        t = mod(t, INTERVAL);
        flip = 1.0-sin(2.0*t*pi)/pi/t;
    }
    flip = sin(flip*pi/2.0)/2.0-0.5;

    mat3 matrix = inverse(mat3(
        vec3(flip+1.0, flip, 0),
        vec3(flip, flip+1.0, 0),
        vec3(0,    0,        1)
    ));
    vec3 uv3 = matrix * vec3(uv, 0);
    uv = uv3.xy * 1.0/(1.0+uv3.z);
    if (abs(uv.x) > 0.5 || abs(uv.y) > 0.5) {
        return;
    }

    if (flip < -0.5) {
        fragColor.rgb = FRONT;
    } else {
        fragColor.rgb = BACK;
    }
}
